#include <iostream>
#include <vector>
int main() {
    for (std::size_t count : {std::size_t{3}, std::size_t{0}}) {
        std::vector<int> nums(count);
        std::cout << nums.size() << " " << nums.size() - 1 << " "
                  << (std::size_t{0} <= nums.size() - 1) << "\n";
    }
}
